"""Render all fixed-threshold results and independent quote-error diagnostics."""
import json
from pathlib import Path
B=Path('reports/metric-multi-latest');data=json.load(open(B/'calibrated-summary.json'));rows=data['rows'];manifest=json.load(open(B/'manifest.json'))
lines=['# Multi-pool flip research — latest complete local tape','',
'Capture: 2026-11-15 23:55–2026-11-16 01:55 UTC. No newer complete capture was present. Binary tape contains 11 Binance symbols and 2,957,811 BBO records. All replay is offline, with no RPC or orders.',
'', 'Ohio translation uses one-way assumptions: Tokyo→Taiwan 25 ms, Tokyo→Ohio 125 ms, chain→Taiwan 175 ms, chain→Ohio machine 0 ms. Both receipt clocks are translated (Binance +100 ms, chain −175 ms), then events reordered. Orders arrive 20 ms after signal. Immediate execution on arrival is assumed; extra sequencing delay is zero. Route latencies are not measured.',
'', 'Each pool is a separate portfolio, starting with approximately 500 USDG worth of that pool’s base token and cash zero, valued at the first eligible Binance bid after 120-second warmup. Position cap is 500 USDG. This is not a shared 500 USDG portfolio; only SPCX initial inventory was specified by the user, so other tokens’ initial inventory is a research assumption. Quantities and initial marks are fixed across threshold variants within each pool. Initial marks are research marks, not acquisition costs. The prior SPCX comparison used a common 139.90 mark and slightly different quantity; its absolute PnL is not directly identical.',
'', 'Buy/sell thresholds are swept symmetrically over 0/2/5/10/15/20/25/30 bps and asymmetrically over 10/0, 10/2, 10/5, 0/10, 2/10, 5/10. Sell edge compares pool proceeds to Binance ask; buy edge compares Binance bid to pool cost. Fees and own size impact are included, gas is zero, USDG/USDT parity is assumed, submitted slippage is 1 bps. No shorting, hedging, fixed hold, or forced liquidation.',
'', '**Flip** means a change in direction between actual simulated fills. One initial sale is zero flips. Repeated buys or sells do not add flips. Buyback episodes count sell→buy transitions, not proof that the entire original token balance was restored. PnL is ending cash plus remaining inventory marked at Binance bid minus initial equity. Excess vs hold includes avoiding underlying price declines and is not all isolated lead-lag premium.',
'', '## Model validation','',
'Source bindings are derived from pinned source-contract storage at keccak(pool,3)+1. Direct calldata updates modify the corresponding compressed word. Bid/ask/mid ratios are calibrated only from the initial pinned provider quote, with no later swaps used to fit them. All 11 initial size quotes match local full-provider execution. Subsequent real swaps are independent validation; ratios do not reproduce changing provider guards/fallbacks. Full-provider execution itself rejects later quotes because its other state is incomplete, so it is not silently used as a fallback.',
'', 'Historical execution updates respect block and transaction index when messages share a receipt time. Decision state sees calldata immediately, and pool logs only on their recorded arrival. Multi-swap transactions are processed in log order. If a pool log precedes its Nitro frame, the decision worker reduces that already-received log locally instead of waiting for a future execution patch. Historical acceptance and transaction index are used for execution-state evaluation, not for filtering calldata signals.',
'', '| Token | Validated swaps | Maximum observed price error (bps) | Assessment |','|---|---:|---:|---|']
audits={}
for m in manifest:
 a=json.load(open(B/(m['symbol']+'-calibrated-audit.json')));audits[m['symbol']]=a
 status='state replay stopped'if a['errors']else ('matched within 0.01 bps'if a['max_price_error_bps']<=0.01 else 'approximation; low-edge results unverified')
 lines.append(f"| {m['symbol']} | {a['counts'].get('swaps',0)} | {a['max_price_error_bps']:.6f} | {status} |")
lines+=['','Errors above are observed maxima on successful historical swaps, not guaranteed bounds for hypothetical fills. MU is excluded from the strategy run because state replay stops. Other high-error pools are shown only as diagnostics.','', '## Fixed symmetric thresholds','', '| Token | Buy/sell bps | Buys | Sells | Flips | PnL USDG | Excess vs hold USDG |','|---|---:|---:|---:|---:|---:|---:|']
for r in rows:
 if r['buy_bps']==r['sell_bps']and r['buy_bps']in ('0','2','5','10','15','20','25','30'):
  lines.append(f"| {r['symbol']} | {r['buy_bps']} | {r['buys']} | {r['sells']} | {r['flips']} | {r['pnl']:+.6f} | {r['excess']:+.6f} |")
lines+=['','## Asymmetric thresholds','', '| Token | Buy bps | Sell bps | Buys | Sells | Flips | PnL USDG | Excess vs hold USDG |','|---|---:|---:|---:|---:|---:|---:|---:|']
for r in rows:
 if r['buy_bps']!=r['sell_bps']:lines.append(f"| {r['symbol']} | {r['buy_bps']} | {r['sell_bps']} | {r['buys']} | {r['sells']} | {r['flips']} | {r['pnl']:+.6f} | {r['excess']:+.6f} |")
lines+=['','## Interpretation limits','', 'This grid is exploratory on one two-hour tape; selecting a best row here is in-sample selection, not out-of-sample performance. Own fills include their immediate depth impact but are not persisted into future historical state. This limitation matters more when flips increase. Gas, revert costs, queue competition, and network jitter are omitted. Initial calibration and successful-swap parity do not establish hypothetical order acceptance.','', 'Artifacts: `calibrated-summary.json`, each `*-calibrated-backtest.json`, `*-calibrated-config.json`, `*-calibrated-audit.json`, and `startup-calibration-parity.json`. Raw binary tape is unchanged. Extracted event/BBO JSONL files are disposable offline working files, not a change to the binary recorder.','', 'Checks: 11 Python causality/inventory/order tests and 9 Rust state/reducer tests; all 11 startup quote parity checks. SPCX extracted transaction count and ingress timestamps match the previous extraction exactly.']
overview=['## Result at a glance','','Lower thresholds increase simulated flips in some approximate models, but the six pools with observed swap errors below 0.01 bps have zero flips across the entire grid. This tape does not establish an increase in reliable tradable profit.','','| Token | Flips at 10/10 bps | Flips at 0/0 bps | 0/0 PnL USDG | 0/0 excess vs hold USDG | Maximum swap error bps |','|---|---:|---:|---:|---:|---:|']
for symbol in ('ETHUSDT','QQQBUSDT','INTCBUSDT','NVDABUSDT'):
 a=next(r for r in rows if r['symbol']==symbol and r['buy_bps']==r['sell_bps']=='0')
 b=next(r for r in rows if r['symbol']==symbol and r['buy_bps']==r['sell_bps']=='10')
 overview.append(f"| {symbol} | {b['flips']} | {a['flips']} | {a['pnl']:+.6f} | {a['excess']:+.6f} | {audits[symbol]['max_price_error_bps']:.6f} |")
overview+=['','Close-swap-parity pools: SPCX, META, TSLA, GOOGL, AAPL, SPY. MU cannot complete state replay. QQQ excess vs hold includes avoiding a subsequent price decline; its absolute PnL remains negative. All values exclude gas and revert costs.','']
lines=lines[:2]+overview+lines[2:]
(B/'FLIP-RESEARCH.md').write_text('\n'.join(lines)+'\n')
